63:   struct Image
64:   {
65:     int width = 0;          // Image width
66:     int height = 0;         // Image height
67:     int channels = 0;       // Number of color channels (e.g., 3 for RGB, 4 for RGBA)
68:     int rowStride = 0;      // Bytes per row
69:     int colStride = 0;      // Bytes per pixel
70:     int chanStride = 0;     // Bytes per channel
71:     int bitDepth = 0;       // Bits per channel
72:     std::vector<std::byte> data;  // Raw pixel data
73: 
74:     template <typename T, int N = 1>
75:     static Image make(int width, int height, bool isPlanar = false)
76:     {
77:       constexpr int sT = static_cast<int>(sizeof(T));
78:       if (isPlanar) {
79:         return Image{
80:           width, height, N,                     // width, height, channels
81:           width * sT,  sT, width * height * sT, // strides: row, column, channel
82:           sT * 8,                               // bit depth
83:           std::vector<std::byte>(width * height * N * sT) };
84:       }
85:       return Image{
86:         width, height, N,             // width, height, channels
87:         width * N * sT,  N * sT, sT,  // strides: row, column, channel
88:         sT * 8,                       // bit depth
89:         std::vector<std::byte>(width * height * N * sT) };
90:     }
91: 
92:     size_t dataSize() const { return data.size(); }
93: 
94:     std::byte* dataPtr() { return data.data(); }
95: 
96:     const std::byte* dataPtr() const { return data.data(); }
97: 
98:     template <typename T>
99:     size_t dataSize() const { return data.size() / sizeof(T); }
100: 
101:     template <typename T>
102:     T* dataPtr() { return reinterpret_cast<T*>(data.data()); }
103: 
104:     template <typename T>
105:     const T* dataPtr() const { return reinterpret_cast<const T*>(data.data()); }
106:   };
107: 
108:   template <typename PixelType>
109:   struct Rgb
110:   {
111:     PixelType r, g, b;
112:   };
113: 
114:   using Rgb8 = Rgb<uint8_t>;
115:   using Rgb16 = Rgb<uint16_t>;
116:   using Rgb32 = Rgb<uint32_t>;
117: 
118:   static_assert(sizeof(Rgb8) == 3, "Rgb8 size must be 3 bytes");
119:   static_assert(sizeof(Rgb16) == 6, "Rgb16 size must be 6 bytes");
120:   static_assert(sizeof(Rgb32) == 12, "Rgb32 size must be 12 bytes");
121: 
122:   template <typename PixelType>
123:   Rgb<PixelType> swap(const Rgb<PixelType>& rgb)
124:   {
125:     return { swap(rgb.b), swap(rgb.g), swap(rgb.r) };
126:   }
